def ft_union(values):
    clean=[]
    for value in values:
        if value is not None and value not in clean:
            clean.append(value)
    if not clean:
        return None
    out=clean[0]
    i=1
    while i<len(clean):
        out=['participant_union',out,clean[i]]
        i+=1
    return out


