def ft_add(rows,seen,term,support):
    ids=[]
    for uid in support:
        if isinstance(uid,int) and uid not in ids:
            ids.append(uid)
    ids=sorted(ids)
    key=repr(term)+'|'+repr(ids)
    if ids and key not in seen:
        seen.add(key)
        rows.append({'term':term,'support_ids':ids})


def ft_bundle(text):
    low=text.lower()
    ci=['confidential_information']
    copies=['copies_of',ci]
    bundle=['information_bundle',ci,copies]
    if ('note' in low or 'extract' in low or 'analys' in low or 'stud' in low or 'summar' in low or 'abstract' in low or 'compilation' in low or 'derivative' in low or 'reproduction' in low or 'record' in low or 'file' in low):
        bundle=['information_bundle',bundle,['derivative_materials_of',ci]]
    return bundle


def ft_exceptions(text):
    low=text.lower()
    values=[]
    if ('without prior written consent' in low or 'without the express written consent' in low or 'without prior written approval' in low or 'without proper written authorization' in low):
        values.append(['authorization_exception',text])
    if ('except as is required in the course of service' in low or 'except as required in the course of service' in low):
        values.append(['purpose_exception',text])
    if 'except as provided herein' in low:
        values.append(['cross_reference_exception',text])
    if not values:
        return ['no_exceptions']
    out=['exception_set',values[0]]
    i=1
    while i<len(values):
        out=['add_exception',out,values[i]]
        i+=1
    return out


def ft_audit_ids(answer,available):
    record=answer.get('complete_source_evidence')
    if not isinstance(record,dict):
        return []
    ids=record.get('unit_ids',[])
    if not isinstance(ids,list):
        return []
    out=[]
    for uid in ids:
        if isinstance(uid,int) and uid in available and uid not in out:
            out.append(uid)
    return out


